import{_ as i,o as t,c as o,a2 as e}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"CDS Jewel -- RGW Multisite Sync","description":"","frontmatter":{"title":"CDS Jewel -- RGW Multisite Sync","date":"2015-08-03T00:00:00.000Z","updated":"2015-08-04T00:00:00.000Z","tags":["Ceph","RGW","Multi","site Sync","Distributed Storage","CephFS"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2015/CDS_Jewel_--_RGW_Multisite_Sync.md","filePath":"posts/2015/CDS_Jewel_--_RGW_Multisite_Sync.md","lastUpdated":1780459816000}'),s={name:"posts/2015/CDS_Jewel_--_RGW_Multisite_Sync.md"};function n(r,l,_,a,p,g){return t(),o("div",null,[...l[0]||(l[0]=[e('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议主题</strong>： Ceph RGW 多站点同步配置改进</p><p><strong>会议时间</strong>： 未提及</p><p><strong>参会人员</strong>： 未提及</p><p><strong>会议内容</strong>：</p><p><strong>一、多站点配置蓝图概述</strong></p><ol><li><strong>新区域（Realm）</strong>： 引入区域概念，当前系统视为单个区域，未来可支持多区域。</li><li><strong>新周期（Period）</strong>： 引入周期概念，确保在达到 Must Run 区域时，不会丢失数据和信息。</li><li><strong>元数据同步</strong>： <ul><li>主节点上执行元数据操作并锁定。</li><li>从节点应用更改前同步元数据日志。</li><li>保留元数据版本向量，记录周期变化。</li></ul></li><li><strong>数据同步</strong>： <ul><li>使用与元数据同步相同的方法进行数据同步。</li><li>改进同步效率，可选全量同步或快速同步。</li></ul></li><li><strong>主动-主动复制（Active-Active Replication）</strong>： <ul><li>实现网关内部的主动-主动复制。</li><li>支持跨多个区域进行复制，使用时间戳和名称作为决断条件。</li></ul></li><li><strong>网关代理</strong>： <ul><li>移除网关代理，将代理功能集成到网关中，提高效率并简化配置。</li></ul></li><li><strong>推送通知</strong>： <ul><li>添加推送通知功能，将最近发生的更改立即通知相关区域。</li></ul></li></ol><p><strong>二、讨论的主要议题</strong></p><ol><li>元数据同步和数据同步的改进方案。</li><li>主动-主动复制的设计和实现。</li><li>网关代理的集成和功能优化。</li></ol><p><strong>三、决定的事项</strong></p><ol><li>采用新周期概念，确保数据同步的可靠性。</li><li>在网关内部实现主动-主动复制。</li><li>移除网关代理，将代理功能集成到网关中。</li><li>添加推送通知功能，提高数据同步的效率。</li></ol><p><strong>四、后续行动计划</strong></p><ol><li>完成元数据同步和数据同步的改进方案设计。</li><li>开发主动-主动复制功能。</li><li>集成网关代理功能。</li><li>实现推送通知功能。</li></ol><p><strong>五、其他</strong></p><ol><li>讨论并解决不同区域之间的冲突和数据一致性保证。</li><li>优化数据同步效率。</li><li>制定详细的开发计划和时间表。</li></ol>',15)])])}const d=i(s,[["render",n]]);export{c as __pageData,d as default};
